package org.daidai.modules.music;

import android.app.*;
import android.content.*;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;
import org.daidai.modules.shared.Ui;
import org.daidai.modules.shared.Texts;

/** Folder-backed songs with independent queue, playlist and favourite references. */
public final class MusicLibraryScreen {
    public static final int PICK_LYRICS=741,PICK_COVER=742;
    private static final WeakHashMap<Activity,MusicLibraryScreen> INSTANCES=new WeakHashMap<>();
    private final Activity a;
    private Runnable changed;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler main=new Handler(Looper.getMainLooper());
    private final ArrayList<Dialog> dialogs=new ArrayList<>();
    private final ArrayList<Runnable> scanCallbacks=new ArrayList<>();
    private final LinkedHashSet<String> folderUris=new LinkedHashSet<>(),selected=new LinkedHashSet<>();
    private final HashSet<String> deleting=new HashSet<>();
    private boolean scanning;
    private String pendingUri,filter=MusicCollections.ALL;
    private Runnable afterEdit;
    private LinearLayout pageRoot,songsHost;

    private MusicLibraryScreen(Activity activity,Runnable callback){a=activity;changed=callback;}
    private static MusicLibraryScreen get(Activity a,Runnable changed){MusicLibraryScreen screen=INSTANCES.get(a);if(screen==null){screen=new MusicLibraryScreen(a,changed);INSTANCES.put(a,screen);}else if(changed!=null)screen.changed=changed;return screen;}
    private String t(String key,Object...args){return Texts.get(a,key,args);}
    public static View createPage(Activity a,Runnable changed){MusicLibraryScreen screen=get(a,changed);return screen.createContent();}
    public static void open(Activity a,Runnable changed){MusicLibraryScreen screen=get(a,changed);screen.dialog(screen.t("library_my_songs"),screen.createContent());}
    public static void openPlaylists(Activity a,Runnable changed){get(a,changed).chooseViewPlaylist();}
    public static void openFavorites(Activity a,Runnable changed){MusicLibraryScreen screen=get(a,changed);screen.selectFilter(MusicCollections.FAVORITES);}
    public static void edit(Activity a,MusicLibrary.Track track,Runnable changed){get(a,changed).editTrack(track.uri,changed);}
    public static boolean toggleFavorite(Activity a,MusicLibrary.Track track,Runnable changed){MusicLibrary.discover(a,Collections.singleton(track));boolean value=MusicCollections.toggleFavorite(a,track.uri);if(changed!=null)changed.run();return value;}
    public static boolean onActivityResult(Activity a,int request,int result,Intent data){return onActivityResult(a,request,result,data,null);}
    public static boolean onActivityResult(Activity a,int request,int result,Intent data,Runnable changed){if(request!=PICK_LYRICS&&request!=PICK_COVER)return false;return get(a,changed).result(request,result,data);}
    public static void destroy(Activity a){MusicLibraryScreen screen=INSTANCES.remove(a);if(screen!=null){screen.worker.shutdownNow();screen.main.removeCallbacksAndMessages(null);for(Dialog dialog:new ArrayList<>(screen.dialogs))if(dialog.isShowing())dialog.dismiss();screen.dialogs.clear();screen.scanCallbacks.clear();}}
    private LinearLayout box(){LinearLayout b=Ui.column(a);b.setPadding(Ui.dp(a,22),Ui.dp(a,10),Ui.dp(a,22),Ui.dp(a,12));return b;}
    private ScrollView scroll(LinearLayout b){ScrollView view=new ScrollView(a);view.addView(b);return view;}
    private AlertDialog track(AlertDialog dialog){dialogs.add(dialog);dialog.setOnDismissListener(v->dialogs.remove(dialog));return dialog;}
    private AlertDialog dialog(String title,LinearLayout content){AlertDialog dialog=track(new AlertDialog.Builder(a).setTitle(title).setView(scroll(content)).setNegativeButton(t("music_close"),null).create());dialog.show();return dialog;}
    private void notifyChanged(){if(changed!=null)changed.run();}
    private void toast(String key){Ui.toast(a,t(key),Toast.LENGTH_SHORT).show();}

    private LinearLayout createContent(){pageRoot=box();LinearLayout first=Ui.row(pageRoot);Ui.cell(first,t("library050_refresh_folder"),()->scanFolder(this::renderSongs));Ui.cell(first,t("music_search"),()->MusicSearchScreen.open(a,visibleTracks(),song->{MusicLibrary.addToQueue(a,Collections.singleton(song));notifyChanged();}));LinearLayout second=Ui.row(pageRoot);Ui.cell(second,"♥ "+t("library_favorites"),()->selectFilter(MusicCollections.FAVORITES));Ui.cell(second,t("library_playlists"),this::chooseViewPlaylist);songsHost=Ui.column(a);pageRoot.addView(songsHost);renderSongs();main.post(()->{if(!a.isDestroyed())scanFolder(this::renderSongs);});return pageRoot;}
    private void selectFilter(String value){filter=value;selected.clear();if(pageRoot==null||!pageRoot.isAttachedToWindow()){dialog(t("library_my_songs"),createContent());return;}renderSongs();}
    private String filterName(){return MusicCollections.ALL.equals(filter)?t("music060_all_songs"):MusicCollections.FAVORITES.equals(filter)?t("library_favorites"):filter;}
    private ArrayList<MusicLibrary.Track> tracks(Collection<String> uris){ArrayList<MusicLibrary.Track> rows=new ArrayList<>();for(String uri:uris){MusicLibrary.Track song=MusicLibrary.find(a,uri);if(song!=null)rows.add(song);}return rows;}
    private ArrayList<MusicLibrary.Track> visibleTracks(){if(!MusicCollections.builtIn(filter)&&!MusicCollections.playlistNames(a).contains(filter))filter=MusicCollections.ALL;ArrayList<MusicLibrary.Track> rows=tracks(folderUris);if(!MusicCollections.ALL.equals(filter)){Set<String> allowed=MusicCollections.FAVORITES.equals(filter)?MusicCollections.favorites(a):MusicCollections.playlist(a,filter);rows.removeIf(song->!allowed.contains(song.uri));}return rows;}
    private void scanFolder(Runnable ready){
        if(ready!=null)scanCallbacks.add(ready);if(scanning)return;String tree=a.getSharedPreferences("music_module",0).getString("storage_tree_uri","");if(tree.isEmpty()){folderUris.clear();finishScan();return;}scanning=true;
        ProgressDialog progress=new ProgressDialog(a);progress.setMessage(t("library_scanning"));progress.setCancelable(false);dialogs.add(progress);progress.show();
        worker.execute(()->{ArrayList<MusicLibrary.Track> rows=new ArrayList<>();boolean failed=false;try{rows=MusicFolder.loadChecked(a,tree);MusicLibrary.discover(a,rows);}catch(InterruptedException e){Thread.currentThread().interrupt();return;}catch(Exception e){failed=true;}final ArrayList<MusicLibrary.Track> found=rows;final boolean error=failed;main.post(()->{scanning=false;if(a.isDestroyed())return;progress.dismiss();dialogs.remove(progress);folderUris.clear();for(MusicLibrary.Track song:found){MusicLibrary.Track canonical=MusicLibrary.find(a,song.uri);if(canonical!=null)folderUris.add(canonical.uri);}finishScan();if(error)Ui.note(a,t("library_my_songs"),t("library_folder_failed"));});});
    }
    private void finishScan(){ArrayList<Runnable> callbacks=new ArrayList<>(scanCallbacks);scanCallbacks.clear();for(Runnable callback:callbacks)callback.run();}

    private void renderSongs(){
        if(songsHost==null)return;songsHost.removeAllViews();ArrayList<MusicLibrary.Track> rows=visibleTracks();HashSet<String> available=new HashSet<>();for(MusicLibrary.Track song:rows)available.add(song.uri);selected.retainAll(available);
        LinearLayout heading=Ui.row(songsHost);TextView name=Ui.text(a,filterName(),18);name.setTag("music060_playlist_heading");heading.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button settings=Ui.button(heading,"⚙",this::managePlaylist);settings.setContentDescription(t("music060_manage_playlist",filterName()));settings.setEnabled(!MusicCollections.builtIn(filter));((LinearLayout.LayoutParams)settings.getLayoutParams()).width=Ui.dp(a,48);
        if(a.getSharedPreferences("music_module",0).getString("storage_tree_uri","").isEmpty()){songsHost.addView(Ui.text(a,t("music_folder_required"),15));return;}
        Button addPlaylist=Ui.button(songsHost,t("music060_selected_to_playlist"),()->chooseDestination(new ArrayList<>(selected)));
        Button addQueue=Ui.button(songsHost,t("library_add_selected"),()->{MusicLibrary.addToQueue(a,tracks(selected));notifyChanged();toast("library_added_to_queue");});Button delete=Ui.button(songsHost,t("music060_delete_selected"),()->deleteFiles(new ArrayList<>(selected),this::renderSongs));
        CheckBox all=new CheckBox(a);all.setText(t("music060_select_all"));all.setTextColor(Ui.INK);all.setButtonTintList(android.content.res.ColorStateList.valueOf(Ui.BLUE));songsHost.addView(all,new LinearLayout.LayoutParams(-1,-2));
        final boolean[] syncing={false};ArrayList<CheckBox> checks=new ArrayList<>();Runnable update=()->{syncing[0]=true;all.setChecked(!rows.isEmpty()&&selected.containsAll(available));all.setEnabled(!rows.isEmpty());syncing[0]=false;addQueue.setEnabled(!selected.isEmpty());addPlaylist.setEnabled(!selected.isEmpty());delete.setEnabled(!selected.isEmpty());};
        all.setOnCheckedChangeListener((button,on)->{if(syncing[0])return;if(on)selected.addAll(available);else selected.removeAll(available);for(int i=0;i<checks.size();i++)checks.get(i).setChecked(selected.contains(rows.get(i).uri));update.run();});
        LinearLayout list=Ui.column(a);songsHost.addView(list);if(rows.isEmpty())list.addView(Ui.text(a,t("library_no_songs"),15));
        for(MusicLibrary.Track song:rows){LinearLayout row=Ui.row(list);CheckBox check=new CheckBox(a);check.setButtonTintList(android.content.res.ColorStateList.valueOf(Ui.BLUE));check.setContentDescription(t("music060_select_song",song.title));check.setChecked(selected.contains(song.uri));checks.add(check);row.addView(check);check.setOnCheckedChangeListener((button,on)->{if(on)selected.add(song.uri);else selected.remove(song.uri);update.run();});LinearLayout content=Ui.column(a);row.addView(content,new LinearLayout.LayoutParams(0,-2,1));MusicCredits.songRow(content,song,song.title,()->songActions(song));}update.run();
    }

    private void chooseViewPlaylist(){LinearLayout b=box();AlertDialog[] chooser={null};Ui.button(b,t("library_create_playlist"),()->playlistName(null,value->{if(chooser[0]!=null)chooser[0].dismiss();selectFilter(value);}));Ui.button(b,t("music060_all_songs"),()->{chooser[0].dismiss();selectFilter(MusicCollections.ALL);});for(String name:MusicCollections.playlistNames(a))Ui.button(b,name,()->{chooser[0].dismiss();selectFilter(name);});chooser[0]=dialog(t("library_playlists"),b);}
    private void managePlaylist(){if(MusicCollections.builtIn(filter))return;final String current=filter;LinearLayout b=box();AlertDialog[] manager={null};Ui.button(b,t("library_rename_playlist"),()->playlistName(current,value->{manager[0].dismiss();selectFilter(value);}));Ui.button(b,t("library_delete_playlist"),()->{AlertDialog confirmation=track(new AlertDialog.Builder(a).setTitle(t("library_delete_playlist")).setMessage(t("library_delete_playlist_confirm",current)).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("library_delete"),(d,w)->{MusicCollections.deletePlaylist(a,current);manager[0].dismiss();selectFilter(MusicCollections.ALL);}).create());confirmation.show();});manager[0]=dialog(current,b);}
    private void playlistName(String old,Consumer<String> saved){LinearLayout b=box();EditText name=input(b,t("library_playlist_name"),old==null?"":old,InputType.TYPE_CLASS_TEXT);AlertDialog d=track(new AlertDialog.Builder(a).setTitle(t(old==null?"library_create_playlist":"library_rename_playlist")).setView(b).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("music_save"),null).create());d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String raw=name.getText().toString().trim();boolean ok=old==null?MusicCollections.createPlaylist(a,raw):old.equals(raw)||MusicCollections.renamePlaylist(a,old,raw);if(!ok){name.setError(t("library_bad_playlist_name"));return;}String value=MusicCollections.normalizedName(raw);d.dismiss();saved.accept(value);}));d.show();}
    private void chooseDestination(Collection<String> uris){if(uris.isEmpty()){toast("library_select_songs");return;}ArrayList<String> snapshot=new ArrayList<>(uris);LinearLayout b=box();AlertDialog[] chooser={null};Ui.button(b,t("library_create_playlist"),()->playlistName(null,name->{MusicCollections.add(a,name,snapshot);if(chooser[0]!=null)chooser[0].dismiss();toast("library_added_to_playlist");renderSongs();}));for(String name:MusicCollections.playlistNames(a))Ui.button(b,name,()->{MusicCollections.add(a,name,snapshot);chooser[0].dismiss();toast("library_added_to_playlist");renderSongs();});chooser[0]=dialog(t("music060_selected_to_playlist"),b);}

    private void songActions(MusicLibrary.Track song){LinearLayout b=box();AlertDialog[] actions={null};Runnable updated=()->{if(actions[0]!=null)actions[0].dismiss();renderSongs();};Ui.button(b,t("music_edit_metadata"),()->editTrack(song.uri,updated));Ui.button(b,t("library_add_to_queue"),()->{MusicLibrary.addToQueue(a,Collections.singleton(song));notifyChanged();});Ui.button(b,(MusicCollections.isFavorite(a,song.uri)?"♥ ":"♡ ")+t(MusicCollections.isFavorite(a,song.uri)?"library_unfavorite":"library_favorite"),()->{MusicCollections.toggleFavorite(a,song.uri);notifyChanged();updated.run();});Ui.button(b,t("library_add_to_playlist"),()->chooseDestination(Collections.singleton(song.uri)));if(!MusicCollections.ALL.equals(filter))Ui.button(b,t("library_remove_from_playlist"),()->{AlertDialog confirmation=track(new AlertDialog.Builder(a).setMessage(t("library_remove_confirm")).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("library_remove"),(d,w)->{if(MusicCollections.FAVORITES.equals(filter)){if(MusicCollections.isFavorite(a,song.uri))MusicCollections.toggleFavorite(a,song.uri);}else MusicCollections.remove(a,filter,Collections.singleton(song.uri));notifyChanged();updated.run();}).create());confirmation.show();});Ui.button(b,t("library050_delete_file"),()->deleteFiles(Collections.singleton(song.uri),updated));actions[0]=dialog(song.title,b);}
    private void deleteFiles(Collection<String> uris,Runnable refreshed){
        ArrayList<String> snapshot=new ArrayList<>(uris);snapshot.removeIf(deleting::contains);if(snapshot.isEmpty())return;String message=snapshot.size()==1?t("library050_delete_file_confirm",Optional.ofNullable(MusicLibrary.find(a,snapshot.get(0))).map(song->song.title).orElse("")):t("music060_delete_selected_confirm",snapshot.size());
        AlertDialog confirm=track(new AlertDialog.Builder(a).setTitle(t("library050_delete_file")).setMessage(message).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("library_delete"),(dialog,which)->{deleting.addAll(snapshot);String tree=a.getSharedPreferences("music_module",0).getString("storage_tree_uri","");worker.execute(()->{ArrayList<String> deleted=new ArrayList<>();int failures=0;for(String uri:snapshot){if(Thread.currentThread().isInterrupted())break;try{MusicFolder.delete(a,tree,uri);deleted.add(uri);}catch(Exception error){failures++;}}final int failed=failures;main.post(()->{deleting.removeAll(snapshot);if(a.isDestroyed())return;folderUris.removeAll(deleted);selected.removeAll(deleted);notifyChanged();refreshed.run();if(failed>0)Ui.note(a,t("library050_delete_file"),t("music060_delete_partial",deleted.size(),failed));else toast("library050_file_deleted");});});}).create());confirm.show();
    }

    private EditText input(LinearLayout b,String label,String value,int type){if(!label.isEmpty())b.addView(Ui.text(a,label,14));EditText field=Ui.input(b,"",type);field.setText(value);field.setPadding(Ui.dp(a,13),Ui.dp(a,10),Ui.dp(a,13),Ui.dp(a,10));GradientDrawable background=new GradientDrawable();background.setColor(0xffedf3fd);background.setCornerRadius(Ui.dp(a,8));field.setBackground(background);LinearLayout.LayoutParams layout=(LinearLayout.LayoutParams)field.getLayoutParams();layout.setMargins(Ui.dp(a,3),0,Ui.dp(a,3),Ui.dp(a,8));return field;}
    private final class PeopleFields {
        final LinearLayout names;final ArrayList<EditText> fields=new ArrayList<>();final String role;
        PeopleFields(LinearLayout host,String role,String initial){this.role=role;LinearLayout heading=Ui.row(host);heading.addView(Ui.text(a,MusicCredits.label(a,role),14),new LinearLayout.LayoutParams(0,-2,1));Button plus=Ui.button(heading,"+",()->add("",true));plus.setContentDescription(t("music060_add_person",MusicCredits.label(a,role)));((LinearLayout.LayoutParams)plus.getLayoutParams()).width=Ui.dp(a,48);names=Ui.column(a);host.addView(names);for(String name:MusicPeople.split(initial))add(name,false);}
        void add(String value,boolean focus){LinearLayout row=Ui.row(names);EditText name=input(row,"",value,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_WORDS);name.setSingleLine(true);name.setTag("music060_person_"+role);LinearLayout.LayoutParams layout=(LinearLayout.LayoutParams)name.getLayoutParams();layout.width=0;layout.weight=1;fields.add(name);Button remove=Ui.button(row,"×",()->{fields.remove(name);names.removeView(row);});remove.setContentDescription(t("music060_remove_person",MusicCredits.label(a,role)));((LinearLayout.LayoutParams)remove.getLayoutParams()).width=Ui.dp(a,48);if(focus)name.requestFocus();}
        String value(){ArrayList<String> names=new ArrayList<>();for(EditText field:fields)names.add(field.getText().toString());return MusicPeople.join(names);}
    }
    private final class TagFields {
        final LinearLayout tags;final ArrayList<EditText> fields=new ArrayList<>();
        TagFields(LinearLayout host,String initial){LinearLayout heading=Ui.row(host);heading.addView(Ui.text(a,t("music_meta_tags"),14),new LinearLayout.LayoutParams(0,-2,1));Button plus=Ui.button(heading,"+",()->add("",true));plus.setContentDescription(t("music070_add_tag"));((LinearLayout.LayoutParams)plus.getLayoutParams()).width=Ui.dp(a,48);tags=Ui.column(a);host.addView(tags);for(String value:MusicTags.split(initial))add(value,false);}
        void add(String value,boolean focus){LinearLayout row=Ui.row(tags);EditText field=input(row,"",value,InputType.TYPE_CLASS_TEXT);field.setSingleLine(true);field.setTag("music070_style_tag");LinearLayout.LayoutParams layout=(LinearLayout.LayoutParams)field.getLayoutParams();layout.width=0;layout.weight=1;fields.add(field);Button remove=Ui.button(row,"×",()->{fields.remove(field);tags.removeView(row);});remove.setContentDescription(t("music070_remove_tag"));((LinearLayout.LayoutParams)remove.getLayoutParams()).width=Ui.dp(a,48);if(focus)field.requestFocus();}
        String value(){ArrayList<String> values=new ArrayList<>();for(EditText field:fields)values.add(field.getText().toString());return MusicTags.join(values);}
    }
    private void editTrack(String uri,Runnable after){String tree=a.getSharedPreferences("music_module",0).getString("storage_tree_uri","");worker.execute(()->{boolean allowed=MusicFolder.contains(a,tree,uri);main.post(()->{if(a.isDestroyed())return;if(allowed)editTrackChecked(uri,after);else Ui.note(a,t("music_edit_metadata"),t("library050_edit_requires_folder"));});});}
    private void editTrackChecked(String uri,Runnable after){
        MusicLibrary.Track song=MusicLibrary.find(a,uri);if(song==null)return;LinearLayout b=box();EditText title=input(b,t("music_meta_title"),song.title,InputType.TYPE_CLASS_TEXT);title.setTag("music060_meta_title");PeopleFields composer=new PeopleFields(b,MusicCredits.COMPOSER,song.composer),arranger=new PeopleFields(b,MusicCredits.ARRANGER,song.arranger),vocalist=new PeopleFields(b,MusicCredits.VOCALIST,song.vocalist);EditText notes=input(b,t("music_meta_notes"),song.notes,InputType.TYPE_CLASS_TEXT);TagFields tags=new TagFields(b,song.tags);EditText bpm=input(b,t("music_meta_bpm"),song.bpmText,InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL),rating=input(b,t("music_meta_rating"),song.rating<0?"":Integer.toString(song.rating),InputType.TYPE_CLASS_NUMBER);bpm.setTag("music060_meta_bpm");rating.setTag("music060_meta_rating");Switch pure=new Switch(a);pure.setText(t("music_meta_instrumental"));pure.setButtonTintList(android.content.res.ColorStateList.valueOf(Ui.BLUE));pure.setChecked(song.instrumental);b.addView(pure);Ui.button(b,t("music_import_lrc"),()->pick(uri,PICK_LYRICS,after));Ui.button(b,t("music_import_cover"),()->pick(uri,PICK_COVER,after));b.addView(Ui.text(a,t("library050_metadata_note"),13));b.addView(Ui.text(a,t("music070_lyrics_storage_note"),13));
        AlertDialog d=track(new AlertDialog.Builder(a).setTitle(t("music_edit_metadata")).setView(scroll(b)).setNegativeButton(t("music_cancel"),null).setPositiveButton(t("music_save"),null).create());d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String name=title.getText().toString().trim();if(name.isEmpty()){title.setError(t("library_title_required"));return;}String value;try{value=MusicLibrary.normalizeBpm(bpm.getText().toString());}catch(IllegalArgumentException invalid){bpm.setError(t("library050_bpm_positive_decimal"));return;}int score=number(rating,-1,0,10);if(score==-2)return;MusicLibrary.Track latest=MusicLibrary.find(a,uri);if(latest==null){d.dismiss();return;}MusicLibrary.update(a,latest.withMeta(name,vocalist.value(),composer.value(),arranger.value(),notes.getText().toString().trim(),tags.value(),value,score,pure.isChecked(),latest.lrcPath,latest.coverPath));MusicLibrary.markMetadataEdited(a,uri);notifyChanged();if(after!=null)after.run();renderSongs();d.dismiss();}));d.show();
    }
    private int number(EditText field,int empty,int min,int max){String raw=field.getText().toString().trim();if(raw.isEmpty())return empty;try{int value=Integer.parseInt(raw);if(value<min||value>max)throw new Exception();return value;}catch(Exception error){field.setError(t("library_number_range",min,max));return -2;}}
    private void pick(String uri,int request,Runnable after){pendingUri=uri;afterEdit=after;a.getSharedPreferences("music_module",0).edit().putString("library_pick_uri",uri).putInt("library_pick_request",request).apply();Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(request==PICK_LYRICS?"*/*":"image/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{a.startActivityForResult(intent,request);}catch(Exception error){a.getSharedPreferences("music_module",0).edit().remove("library_pick_uri").remove("library_pick_request").apply();Ui.error(a,error);}}
    private boolean result(int request,int result,Intent data){
        if(request!=PICK_LYRICS&&request!=PICK_COVER)return false;if(pendingUri==null&&a.getSharedPreferences("music_module",0).getInt("library_pick_request",0)==request)pendingUri=a.getSharedPreferences("music_module",0).getString("library_pick_uri",null);a.getSharedPreferences("music_module",0).edit().remove("library_pick_uri").remove("library_pick_request").apply();Runnable callback=afterEdit;afterEdit=null;if(result!=Activity.RESULT_OK||data==null||data.getData()==null||pendingUri==null){pendingUri=null;return true;}String trackUri=pendingUri;pendingUri=null;Uri source=data.getData();worker.execute(()->{
            File cover=null;MusicLyricsImport.Result lyrics=null;boolean committed=false;
            try{
                if(request==PICK_LYRICS)lyrics=MusicLyricsImport.copyToFolder(a,source);
                else{File dir=new File(a.getFilesDir(),"covers");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();cover=File.createTempFile("song-",".cover",dir);try(InputStream in=a.getContentResolver().openInputStream(source);OutputStream out=new FileOutputStream(cover)){if(in==null)throw new IOException();byte[] bytes=new byte[8192];int size;while((size=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedException();out.write(bytes,0,size);}}}
                if(Thread.currentThread().isInterrupted())throw new InterruptedException();
                synchronized(MusicLibrary.class){MusicLibrary.Track song=MusicLibrary.find(a,trackUri);if(song==null)return;MusicLibrary.update(a,song.withMeta(song.title,song.vocalist,song.composer,song.arranger,song.notes,song.tags,song.bpmText,song.rating,song.instrumental,lyrics==null?song.lrcPath:lyrics.uri.toString(),cover==null?song.coverPath:cover.getAbsolutePath()));committed=true;}
                main.post(()->{if(!a.isDestroyed()){notifyChanged();if(callback!=null)callback.run();renderSongs();toast("library_file_imported");}});
            }catch(Exception error){if(!(error instanceof InterruptedException)&&!Thread.currentThread().isInterrupted())main.post(()->{if(!a.isDestroyed())Ui.error(a,error);});}
            finally{if(!committed){if(cover!=null)cover.delete();if(lyrics!=null)lyrics.discard(a);}}
        });return true;
    }
}
